def semver_sort(versions):
    def parse(v):
        main = v
        build = None
        if '+' in main:
            main, build = main.split('+', 1)
        pre = None
        if '-' in main:
            main, pre = main.split('-', 1)
        parts = main.split('.')
        major, minor, patch = int(parts[0]), int(parts[1]), int(parts[2])
        has_pre = pre is not None
        pre_ids = []
        if has_pre:
            for ident in pre.split('.'):
                if ident.isdigit():
                    pre_ids.append((0, int(ident), ''))
                else:
                    pre_ids.append((1, 0, ident))
        # version without prerelease sorts after one with prerelease
        pre_flag = 0 if has_pre else 1
        return (major, minor, patch, pre_flag, pre_ids)

    return sorted(versions, key=parse)

